#!/usr/bin/env python3
"""
META Stock Anomaly Detection

This script fetches META stock data for the last 14 days,
detects anomalous trading days using Z-score analysis,
and generates comprehensive reports.
"""

import yfinance as yf
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from datetime import datetime, timedelta
import json
import warnings

# Suppress yfinance warnings
warnings.filterwarnings('ignore')

def fetch_stock_data(ticker: str, days: int = 14) -> pd.DataFrame:
    """
    Fetch stock data for the specified ticker and number of days.

    Args:
        ticker: Stock ticker symbol
        days: Number of days to fetch (default: 14)

    Returns:
        DataFrame with stock data

    Raises:
        Exception: If data fetching fails
    """
    end_date = datetime.now()
    start_date = end_date - timedelta(days=days + 5)  # Extra days to ensure we get 14 trading days

    try:
        print(f"Fetching {ticker} stock data from {start_date.strftime('%Y-%m-%d')} to {end_date.strftime('%Y-%m-%d')}...")

        # Download stock data
        stock_data = yf.download(
            ticker, 
            start=start_date, 
            end=end_date, 
            progress=False
        )

        if stock_data.empty:
            raise ValueError(f"No data found for ticker {ticker}")

        # Keep only the last 14 trading days
        stock_data = stock_data.tail(days)

        print(f"Successfully fetched {len(stock_data)} trading days of data")
        return stock_data

    except Exception as e:
        raise Exception(f"Failed to fetch stock data: {str(e)}")

def calculate_anomalies(data: pd.DataFrame, threshold: float = 2.0) -> pd.DataFrame:
    """
    Calculate daily returns and detect anomalies using Z-score analysis.

    Args:
        data: Stock data DataFrame
        threshold: Z-score threshold for anomaly detection

    Returns:
        DataFrame with returns, Z-scores, and anomaly flags
    """
    # Calculate daily returns
    data['Daily_Return'] = data['Close'].pct_change()

    # Remove NaN values (first day has no previous day for return calculation)
    data = data.dropna()

    if len(data) == 0:
        raise ValueError("No valid data points for analysis")

    # Calculate Z-scores
    returns_mean = data['Daily_Return'].mean()
    returns_std = data['Daily_Return'].std()

    if returns_std == 0:
        print("Warning: Standard deviation is 0, all returns are identical")
        data['Z_Score'] = 0
    else:
        data['Z_Score'] = (data['Daily_Return'] - returns_mean) / returns_std

    # Identify anomalies
    data['Is_Anomaly'] = (np.abs(data['Z_Score']) > threshold)

    print(f"Analysis complete:")
    print(f"  - Mean daily return: {returns_mean:.4f} ({returns_mean*100:.2f}%)")
    print(f"  - Standard deviation: {returns_std:.4f} ({returns_std*100:.2f}%)")
    print(f"  - Anomalies detected: {data['Is_Anomaly'].sum()} out of {len(data)} days")

    return data

def create_visualization(data: pd.DataFrame, ticker: str) -> None:
    """
    Create and save a matplotlib visualization of the stock data and anomalies.

    Args:
        data: Processed stock data with anomaly flags
        ticker: Stock ticker symbol
    """
    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 10))

    # Plot 1: Stock price with anomalous days highlighted
    ax1.plot(data.index, data['Close'], 'b-', linewidth=2, label='Close Price')

    # Highlight anomalous days
    anomaly_data = data[data['Is_Anomaly']]
    if not anomaly_data.empty:
        ax1.scatter(anomaly_data.index, anomaly_data['Close'], 
                   color='red', s=100, zorder=5, label='Anomalous Days')

    ax1.set_title(f'{ticker} Stock Price - Last 14 Trading Days', fontsize=14, fontweight='bold')
    ax1.set_ylabel('Price ($)', fontsize=12)
    ax1.grid(True, alpha=0.3)
    ax1.legend()

    # Format x-axis dates
    ax1.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d'))
    ax1.xaxis.set_major_locator(mdates.DayLocator(interval=2))

    # Plot 2: Daily returns with Z-score threshold lines
    returns_pct = data['Daily_Return'] * 100
    colors = ['red' if anomaly else 'blue' for anomaly in data['Is_Anomaly']]

    bars = ax2.bar(data.index, returns_pct, color=colors, alpha=0.7)

    # Add threshold lines
    ax2.axhline(y=0, color='black', linestyle='-', alpha=0.3)

    # Calculate threshold values in percentage terms
    returns_mean = data['Daily_Return'].mean()
    returns_std = data['Daily_Return'].std()
    upper_threshold = (returns_mean + 2 * returns_std) * 100
    lower_threshold = (returns_mean - 2 * returns_std) * 100

    ax2.axhline(y=upper_threshold, color='red', linestyle='--', alpha=0.7, label='Z-score = +2')
    ax2.axhline(y=lower_threshold, color='red', linestyle='--', alpha=0.7, label='Z-score = -2')

    ax2.set_title('Daily Returns with Anomaly Detection', fontsize=14, fontweight='bold')
    ax2.set_xlabel('Date', fontsize=12)
    ax2.set_ylabel('Daily Return (%)', fontsize=12)
    ax2.grid(True, alpha=0.3)
    ax2.legend()

    # Format x-axis dates
    ax2.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d'))
    ax2.xaxis.set_major_locator(mdates.DayLocator(interval=2))

    plt.tight_layout()
    plt.savefig('anomalies.png', dpi=300, bbox_inches='tight')
    plt.close()

    print("Visualization saved as 'anomalies.png'")

