            'daily_return_pct': float(row['Daily_Return'] * 100) if not pd.isna(row['Daily_Return']) else None,
            'z_score': float(row['Z_Score']) if not pd.isna(row['Z_Score']) else None,
            'is_anomaly': bool(row['Is_Anomaly'])
        })

    # Save to JSON file
    with open('anomaly_report.json', 'w') as f:
        json.dump(summary, f, indent=2)

    print("JSON report saved as 'anomaly_report.json'")

